#!/usr/bin/env node
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    RelicGameRarity, RelicGameUnlockType, RelicGameRow, RELIC_GAME_TABLE, RELIC_GAME_TABLE_BY_INDEX
 * depends    —
 * used by    —
 * ────────────────────────────────────────────────── generated by `pnpm map` ──
 */
/**
 * Emit the game's own relic table: every relic slot by save index, with what it grants and how it
 * is unlocked.
 *
 * Reads the versioned `facts/<version>/relics.json` fixture. `RELIC_TEMPLATES` is the wiki's list
 * and stops at the relics that were out when it was read; this table is every slot a save carries.
 */
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const here = path.dirname(fileURLToPath(import.meta.url))
const root = path.resolve(here, '..')
const VERSION = 'v29.2.0'
const factPath = path.join(root, 'facts', VERSION, 'relics.json')
const outPath = path.join(root, 'src', 'data', 'generated', 'relic-game-table.generated.ts')

if (!fs.existsSync(factPath)) {
  console.error(`missing ${path.relative(root, factPath)}`)
  console.error(`  Supply the versioned fixture at ${factPath}, then rerun this generator.`)
  process.exit(1)
}

const relics = JSON.parse(fs.readFileSync(factPath, 'utf8')).relics ?? []

// Refuse a table with a hole in it: a save reads this by index, and a missing row shifts nothing
// but answers "unknown" for a relic the game defines.
const missing = relics.map((relic, position) => (relic.index === position ? null : position)).filter(v => v !== null)
if (!relics.length || missing.length) {
  console.error(`relics.json is not one row per index from 0: first mismatch at ${missing[0] ?? 0}. Not emitting.`)
  process.exit(1)
}

const q = value => JSON.stringify(value)
const rows = relics
  .map(r => `  { index: ${r.index}, internalName: ${q(r.internalName)}, rarity: ${q(r.rarity)}, benefit: ${r.benefit}, stat: ${q(r.benefitType)}, unlockType: ${q(r.unlockType)}, unlockCost: ${r.unlockCost}, releaseDate: ${q(r.releaseDate)} },`)
  .join('\n')
const union = values => [...new Set(values)].map(q).join(' | ')

const source = `/**
 * GENERATED by \`scripts/build-relic-game-table.mjs\` from facts/${VERSION}. Do not edit.
 *
 * Every relic slot the game defines, by save index (\`relicsUnlocked[index]\`). This is the game's
 * table, so it includes relics that are not out yet: \`releaseDate\` says when each one is.
 */
export type RelicGameRarity = ${union(relics.map(r => r.rarity))}

/** How the game says a relic is unlocked. \`Medals\` is an event relic: earn that many medals in its event. */
export type RelicGameUnlockType = ${union(relics.map(r => r.unlockType))}

export interface RelicGameRow {
  /** Save index: the relic's position in \`relicsUnlocked\`. */
  index: number
  /** The game's own name for the relic, unspaced. */
  internalName: string
  rarity: RelicGameRarity
  /** As stored: a fraction for a percentage (0.02 is 2%), seconds for WallRebuild, metres for BotRange. */
  benefit: number
  /** The stat the relic adds to, by the game's name for it. */
  stat: string
  unlockType: RelicGameUnlockType
  /** Medals, guild tokens, wave or rank, depending on \`unlockType\`; 0 for a gift or purchase. */
  unlockCost: number
  /** ISO date the game attaches to the relic. A date in the future is a relic that is not out yet. */
  releaseDate: string
}

export const RELIC_GAME_TABLE: readonly RelicGameRow[] = [
${rows}
] as const

export const RELIC_GAME_TABLE_BY_INDEX: ReadonlyMap<number, RelicGameRow> = new Map(
  RELIC_GAME_TABLE.map(relic => [relic.index, relic]),
)
`

fs.writeFileSync(outPath, source)
console.log(`  wrote ${path.relative(root, outPath)}  (${relics.length} relics)`)
